/*
 * CoAP Server — coap-simple.h (Board 1)
 * Uses callback-based API:
 *   coap.server(callback, "path");
 *   coap.sendResponse(ip, port, msgid, resp);
 *
 * Endpoints:
 *   /light           — PUT "1"/"ON" to turn LED on, "0"/"OFF" to turn off
 *   /sensor/temperature — GET returns mock JSON {"temp": 24.5, "unit": "C"}
 */

#include <coap-simple.h>
#include <WiFiUdp.h>

WiFiUDP udp;
Coap coap(udp);

const int LED_PIN = 5;

void callback_light(CoapPacket &packet, IPAddress ip, int port)
{
  String payload = String(packet.payload);

  Serial.print("[Server] /light payload: '");
  Serial.print(payload);
  Serial.println("'");

  if (payload == "1" || payload == "ON")
  {
    digitalWrite(LED_PIN, HIGH);
    Serial.println("[Server] LED ON");
    coap.sendResponse(ip, port, packet.messageid, "LED turned ON");
  }
  else if (payload == "0" || payload == "OFF")
  {
    digitalWrite(LED_PIN, LOW);
    Serial.println("[Server] LED OFF");
    coap.sendResponse(ip, port, packet.messageid, "LED turned OFF");
  }
  else
  {
    int state = digitalRead(LED_PIN);
    String response = "LED status: " + String(state ? "ON" : "OFF");
    coap.sendResponse(ip, port, packet.messageid, response.c_str());
  }
}

void callback_temp(CoapPacket &packet, IPAddress ip, int port)
{
  float mockTemp = 24.5;
  String response = "{\"temp\": " + String(mockTemp) + ", \"unit\": \"C\"}";
  coap.sendResponse(ip, port, packet.messageid, response.c_str());
}

void setup()
{
  Serial.begin(115200);
  delay(500);
  Serial.println("=== coap-simple.h Server Starting ===");

  pinMode(LED_PIN, OUTPUT);

  coap.server(callback_light, "light");
  coap.server(callback_temp, "sensor/temperature");
  coap.start();

  Serial.println("CoAP Server started on port 5683");
  Serial.println("Endpoints: /light, /sensor/temperature");
}

void loop()
{
  coap.loop();
}

