/*
 * CoAP Client — Board 2
 * Uses CoapClient API to poll the coap-simple.h server on Board1.
 * Toggles an LED on D2 each time it gets a successful response.
 */

#include <CoapClient.h>

CoapClient client;
bool ledState = false;

void setup()
{
  Serial.begin(115200);
  pinMode(2, OUTPUT);
  Serial.println("[Client] CoAP Client starting...");
  delay(2000);
}

void loop()
{
  // GET /sensor/temperature
  CoapResponse tempResp = client.get("/sensor/temperature");
  if (tempResp.valid && tempResp.code == COAP_CONTENT)
  {
    Serial.print("[Client] Temperature: ");
    Serial.println(tempResp.payload);
    ledState = !ledState;
    digitalWrite(2, ledState ? HIGH : LOW);
  }
  else
  {
    Serial.println("[Client] No response from server");
  }

  delay(1000);

  // POST to /light with "ON"
  CoapResponse lightResp = client.put("/light", "1");
  if (lightResp.valid)
  {
    Serial.print("[Client] /light response: ");
    Serial.println(lightResp.payload);
  }

  delay(2000);

  // POST to /light with "OFF"
  lightResp = client.put("/light", "0");
  if (lightResp.valid)
  {
    Serial.print("[Client] /light response: ");
    Serial.println(lightResp.payload);
  }

  delay(2000);
}
